const ids = ["folder:159d84b7cec4a38c","jira:SYN-3","jira:SYN-45","jira:SYN-47"] as const;
const r = [];
for (const id of ids) { const i = await items.read(id); r.push(i.gone? i : {id, text:i.text}); }
return r;

